input.command:
cd "$ARCHON_HORIZON_ROOT/MainProjects/Algebraic-Jacobian-Challenge"; python3 - <<'EOF'
import re,os
def imps(m):
    p=m.replace('.','/')+'.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(p).read(),re.M) if os.path.exists(p) else []
seen,stack=set(),['AlgebraicJacobian.Jacobian']
while stack:
    m=stack.pop()
    if m not in seen: seen.add(m); stack+=imps(m)
print('reachable from headline:',len(seen))
seen2,stack2=set(),['AlgebraicJacobian']
while stack2:
    m=stack2.pop()
    if m not in seen2: seen2.add(m); stack2+=imps(m)
allm={os.path.join(d,f)[:-5].replace('/','.') for d,_,fs in os.walk('AlgebraicJacobian') for f in fs if f.endswith('.lean')}
print('on disk',len(allm),'rooted',len(allm&seen2),'unrooted:',sorted(allm-seen2) or 'none')
EOF
